const ORG_INFO={
  nucleus:{name:'Núcleo',emoji:'🟣',fn:'Centro de control de la célula. Contiene el ADN y dirige todas las actividades celulares, incluyendo la división y síntesis de proteínas.',loc:'Centro de la célula eucariota, rodeado por la envoltura nuclear.',struct:'Envoltura nuclear (doble membrana con poros), nucleoplasma, cromatina (ADN + histonas), nucléolo.',proc:'Replicación del ADN (fase S), transcripción (síntesis de ARNm), exportación de ARN al citoplasma.',diff:'Presente en todas las células eucariotas. Ausente en procariotas, que tienen nucleoide.',path:'Mutaciones en genes nucleares causan cáncer y enfermedades genéticas hereditarias.',cur:'El genoma humano contiene ~3.000 millones de pares de bases. Extendido, el ADN de una sola célula mediría ~2 metros.'},
  nucleolus:{name:'Nucléolo',emoji:'🔵',fn:'Fábrica de ribosomas. Sintetiza ARN ribosómico (ARNr) y ensambla las subunidades ribosómicas.',loc:'Dentro del núcleo, asociado a regiones organizadoras del nucléolo (NOR).',struct:'Sin membrana propia. Compuesto de ARNr en síntesis, proteínas ribosómicas y cromatina perinucleolar.',proc:'Transcripción del ADNr por ARN polimerasa I. Procesamiento del pre-ARNr. Ensamblado de subunidades 40S y 60S.',diff:'Presente en eucariotas. En procariotas, los ribosomas se ensamblan directamente en el citoplasma.',path:'Agrandamiento del nucléolo es marcador de células cancerosas de alta actividad.',cur:'El nucléolo solo es visible durante la interfase. Desaparece cuando la célula entra en mitosis.'},
  mito1:{name:'Mitocondria',emoji:'🔴',fn:'Central energética de la célula. Produce ATP mediante respiración celular aeróbica (fosforilación oxidativa).',loc:'Esparcidas en el citoplasma. Abundantes en células de alta demanda energética (músculo, neurona).',struct:'Doble membrana: externa (lisa) e interna (con crestas). Matriz mitocondrial con ADNmt circular y ribosomas 70S.',proc:'Ciclo de Krebs (matriz), cadena de transporte de electrones (membrana interna), fosforilación oxidativa.',diff:'Animal y vegetal tienen mitocondrias. Procariotas usan la membrana plasmática para respiración.',path:'Enfermedades mitocondriales: Leigh, MELAS. Relacionadas con envejecimiento y diabetes tipo 2.',cur:'Las mitocondrias tienen ADN propio heredado solo por línea materna. Evidencia de endosimbiosis de una proteobacteria α.'},
  mito2:{name:'Mitocondria',emoji:'🔴',fn:'Produce ATP mediante respiración aeróbica (fosforilación oxidativa).',loc:'Esparcida en el citoplasma.',struct:'Doble membrana, crestas mitocondriales, matriz con ADNmt y ribosomas 70S.',proc:'Ciclo de Krebs, cadena respiratoria, fosforilación oxidativa → ATP.',diff:'Animal y vegetal. Ausente en procariotas.',path:'Miopatías mitocondriales, síndrome de Leigh.',cur:'Una sola célula hepática puede contener hasta 2.000 mitocondrias.'},
  mito:{name:'Mitocondria',emoji:'🔴',fn:'Central energética. Produce ATP mediante respiración celular aeróbica.',loc:'Citoplasma de células eucariotas.',struct:'Doble membrana, crestas, matriz con ADNmt.',proc:'Ciclo de Krebs y fosforilación oxidativa.',diff:'Animal y vegetal. Ausente en procariotas.',path:'Enfermedades mitocondriales afectan órganos de alta demanda energética.',cur:'Heredadas por vía materna. Origen endosimbiótico bacteriano confirmado.'},
  er_rough:{name:'Retículo ER Rugoso',emoji:'🟠',fn:'Síntesis de proteínas destinadas a secreción o membrana. Los ribosomas adheridos traducen el ARNm co-traduccionalmente.',loc:'Red de membranas contigua con la envoltura nuclear.',struct:'Cisternas y túbulos membranosos con ribosomas en la cara citosólica.',proc:'Traducción co-traduccional, plegamiento de proteínas, N-glicosilación inicial, envío al Golgi.',diff:'Animal y vegetal. En procariotas, la síntesis ocurre en el citoplasma libre.',path:'Estrés del RE: asociado a diabetes tipo 2, Alzheimer, Parkinson.',cur:'El RER puede ocupar más del 20% del volumen en células secretoras como las pancreáticas.'},
  er_smooth:{name:'Retículo ER Liso',emoji:'🟡',fn:'Síntesis de lípidos, metabolismo de carbohidratos, detoxificación y almacenamiento de calcio.',loc:'Red de túbulos sin ribosomas, conectada al RER.',struct:'Membrana lipídica tubular sin ribosomas.',proc:'Síntesis de fosfolípidos, esteroides. Detoxificación (citocromo P450 en hígado). Liberación de Ca²⁺.',diff:'Animal y vegetal. Muy desarrollado en hepatocitos y células musculares.',path:'Hipertrofia del REL por exposición crónica a tóxicos o fármacos.',cur:'En músculo se llama retículo sarcoplasmático y almacena el calcio que dispara la contracción muscular.'},
  golgi:{name:'Aparato de Golgi',emoji:'🟤',fn:'Modifica, etiqueta y empaqueta proteínas y lípidos en vesículas para transporte intracelular o secreción.',loc:'Próximo al núcleo y al RER.',struct:'Pilas de cisternas aplanadas (4–8). Cara cis (recibe del RER) y cara trans (envía a destino).',proc:'O-glicosilación, fosforilación, sulfatación. Formación de vesículas secretoras y lisosomales.',diff:'Animal y vegetal. En plantas hay múltiples dictiosomas distribuidos. Ausente en procariotas.',path:'Defectos en glicosilación: enfermedades CDG (congenital disorders of glycosylation).',cur:'Camillo Golgi lo describió en 1898. Se lo llama la "oficina postal de la célula".'},
  lysosome:{name:'Lisosoma',emoji:'🟢',fn:'Compartimento digestivo. Degrada macromoléculas, orgánulos dañados (autofagia) y material extracelular.',loc:'Citoplasma. Abundantes en macrófagos y células de alta actividad catabólica.',struct:'Vesícula con membrana. Interior ácido (pH 4.5–5.0). Contiene +50 hidrolasas ácidas.',proc:'Autofagia, heterofagia, reciclaje celular.',diff:'Exclusivo de células animales. En plantas, la vacuola cumple función equivalente.',path:'Enfermedades de depósito lisosomal: Gaucher, Tay-Sachs, Fabry.',cur:'El pH ácido protege al citoplasma: si la membrana se rompe, las enzimas son inactivas a pH 7.'},
  lysosome2:{name:'Lisosoma',emoji:'🟢',fn:'Degrada macromoléculas y orgánulos dañados mediante hidrólisis ácida.',loc:'Citoplasma de células animales.',struct:'Vesícula con hidrolasas ácidas, pH interno 4.5–5.',proc:'Autofagia, heterofagia, reciclaje.',diff:'Exclusivo de animales. Equivalente funcional: vacuola vegetal.',path:'Enfermedades de depósito lisosomal.',cur:'Las células recambian completamente su contenido cada pocos días gracias a la actividad lisosomal.'},
  ribosome:{name:'Ribosoma',emoji:'⚫',fn:'Sintetiza proteínas mediante traducción del ARN mensajero. No tiene membrana.',loc:'Libre en citoplasma o adherido al RER. También en mitocondrias y cloroplastos.',struct:'Dos subunidades: 40S + 60S = 80S en eucariotas. Compuesto por ARNr y proteínas.',proc:'Traducción: iniciación, elongación (adición de aminoácidos), terminación.',diff:'Eucariotas: 80S. Procariotas y orgánulos semiautónomos: 70S.',path:'Ribosomiopatías: Síndrome de Diamond-Blackfan.',cur:'Un ribosoma sintetiza ~15 aminoácidos/segundo. Los antibióticos actúan sobre ribosomas 70S bacterianos.'},
  centrosome:{name:'Centrosoma',emoji:'🔵',fn:'Centro organizador de microtúbulos (MTOC). Organiza el huso mitótico durante la división celular.',loc:'Cerca del núcleo. Se duplica antes de la mitosis.',struct:'Dos centriolos perpendiculares (9 tripletes de microtúbulos) rodeados por material pericentriolar.',proc:'Nucleación de microtúbulos. Organización del huso acromático en mitosis y meiosis.',diff:'Presente en células animales. Ausente en células vegetales superiores.',path:'Duplicación anormal del centrosoma puede causar aneuploidía y cáncer.',cur:'Los centriolos también forman la base de cilios y flagelos en células ciliadas.'},
  peroxisome:{name:'Peroxisoma',emoji:'🟡',fn:'Metabolismo de ácidos grasos y detoxificación del peróxido de hidrógeno (H₂O₂).',loc:'Citoplasma. Abundantes en hepatocitos y células renales.',struct:'Vesícula de membrana simple. Sin genoma propio.',proc:'β-oxidación de ácidos grasos de cadena muy larga. Producción y destrucción de H₂O₂ por catalasa.',diff:'Animal y vegetal. En plantas participan en fotorrespiración.',path:'Síndrome de Zellweger (defecto en biogénesis de peroxisomas). Fatal en infancia.',cur:'La catalasa peroxisomal descompone H₂O₂ a 6 millones de moléculas por minuto.'},
  cytoskeleton:{name:'Citoesqueleto',emoji:'🕸️',fn:'Red de filamentos que da forma a la célula, permite el movimiento y el transporte intracelular.',loc:'Todo el citoplasma.',struct:'Tres componentes: microtúbulos (25 nm, tubulina), filamentos de actina (7 nm), filamentos intermedios (10 nm).',proc:'División celular (huso), movimiento (flagelos, cilios), transporte de vesículas.',diff:'Animal y vegetal. En procariotas existen homólogos (FtsZ, MreB).',path:'Disquinesia ciliar primaria, neuropatías axonales.',cur:'Los microtúbulos se despolimerizan y repolimerizan en segundos. La colchicina los bloquea → tratamiento de gota.'},
  membrane:{name:'Membrana Plasmática',emoji:'🌐',fn:'Barrera selectiva que separa el interior celular del exterior y regula el paso de sustancias.',loc:'Límite externo de la célula.',struct:'Bicapa lipídica (fosfolípidos + colesterol) con proteínas integrales y periféricas. Modelo de mosaico fluido.',proc:'Transporte activo y pasivo, endocitosis, exocitosis, reconocimiento celular.',diff:'Universal (todas las células). En vegetal y procariota hay pared celular adicional.',path:'Defectos en canales iónicos: fibrosis quística (CFTR), hipercolesterolemia.',cur:'La membrana tiene solo 7–10 nm de grosor pero contiene miles de proteínas distintas por µm².'},
  chloro1:{name:'Cloroplasto',emoji:'🌿',fn:'Realiza la fotosíntesis: convierte energía lumínica en glucosa, liberando oxígeno.',loc:'Citoplasma de células vegetales fotosintéticas.',struct:'Doble membrana. Interior: estroma + tilacoides apilados (grana). Posee ADN propio y ribosomas 70S.',proc:'Fase luminosa (tilacoides): fotólisis del agua, ATP y NADPH. Ciclo de Calvin (estroma): fijación de CO₂, glucosa.',diff:'Exclusivo de plantas y algas. Ausente en animales y hongos.',path:'Mutaciones en ADN cloroplástico reducen productividad agrícola.',cur:'Origen endosimbiótico: un eucariota fagocitó una cianobacteria hace ~1.500 millones de años.'},
  chloro2:{name:'Cloroplasto',emoji:'🌿',fn:'Fotosíntesis: conversión de luz solar en glucosa y liberación de O₂.',loc:'Citoplasma, especialmente en células del mesófilo foliar.',struct:'Doble membrana, estroma, grana, ADNcp, ribosomas 70S.',proc:'Reacciones luminosas + Ciclo de Calvin.',diff:'Exclusivo de plantas y algas fotosintéticas.',path:'Virus y hongos que destruyen cloroplastos reducen la capacidad fotosintética.',cur:'Un cloroplasto contiene 10–100 copias de su genoma circular (~120–160 genes).'},
  chloro3:{name:'Cloroplasto',emoji:'🌿',fn:'Fotosíntesis y síntesis de aminoácidos, ácidos grasos y vitaminas.',loc:'Citoplasma de células vegetales.',struct:'Doble membrana, tilacoides, estroma con enzimas del ciclo de Calvin.',proc:'Fotólisis, fotofosforilación, ciclo de Calvin.',diff:'Exclusivo de plantas y algas.',path:'Alteraciones fotosintéticas afectan crecimiento vegetal y productividad.',cur:'La clorofila a absorbe luz roja (~680 nm) y azul-violeta (~430 nm), reflejando el verde.'},
  vacuole:{name:'Vacuola Central',emoji:'💧',fn:'Almacena agua, iones, pigmentos y toxinas. Mantiene la turgencia celular (presión de turgor).',loc:'Ocupa hasta el 90% del volumen en células vegetales maduras.',struct:'Membrana llamada tonoplasto. Jugo vacuolar: agua, sales, azúcares, pigmentos (antocianinas).',proc:'Regulación osmótica (turgor), almacenamiento de metabolitos secundarios, función lisosomal en plantas.',diff:'Vegetal: gran vacuola central. Animal: pequeñas vacuolas temporales.',path:'Pérdida de turgor → marchitamiento. Acumulación de oxalato de calcio puede causar daño renal.',cur:'Las antocianinas almacenadas en vacuolas dan colores rojo, azul y violeta a flores y frutos.'},
  plasmodesmata:{name:'Plasmodesmos',emoji:'🔗',fn:'Canales que conectan el citoplasma de células vegetales adyacentes para comunicación y transporte.',loc:'Pared celular entre células vegetales vecinas.',struct:'Canales citoplasmáticos de 30–60 nm, rodeados de membrana plasmática. Contienen el desmotúbulo (RE conectado).',proc:'Transporte de moléculas pequeñas, señales, ARN y proteínas entre células (simplasto).',diff:'Exclusivo de plantas. Equivalente animal: uniones comunicantes (gap junctions).',path:'Virus vegetales se propagan célula a célula a través de plasmodesmos.',cur:'Una célula vegetal puede tener 1.000–100.000 plasmodesmos, formando el simplasto.'},
  cell_wall:{name:'Pared Celular',emoji:'🛡️',fn:'Protección mecánica, soporte estructural y control del volumen por presión de turgor.',loc:'Exterior de la membrana plasmática en plantas.',struct:'Celulosa (microfibrillas) + hemicelulosa + pectinas. Pared primaria (joven) y secundaria (madura, lignina).',proc:'Síntesis de celulosa por celulosa sintasa en membrana. Depósito de lignina en pared secundaria.',diff:'Plantas: celulosa. Hongos: quitina. Bacterias: peptidoglicano. Animales: sin pared.',path:'Celulasas y pectinasas de patógenos degradan la pared → infección.',cur:'La madera es principalmente lignina y celulosa de la pared celular secundaria del xilema.'},
  nucleoid:{name:'Nucleoide',emoji:'🧬',fn:'Región donde se concentra el ADN circular en procariotas. Sin membrana que lo rodee.',loc:'Centro de la célula procariota.',struct:'ADN circular desnudo, superenrollado. Sin histonas (proteínas HU y H-NS participan en compactación).',proc:'Replicación bidireccional desde un único origen (oriC). Transcripción y traducción simultáneas.',diff:'Procariotas: nucleoide (sin membrana). Eucariotas: núcleo con envoltura nuclear.',path:'Mutaciones en el nucleoide = resistencia antibiótica o mayor patogenicidad bacteriana.',cur:'El cromosoma de E. coli tiene ~4,6 millones de pares de bases, compactados en ~1 µm.'},
  plasmid:{name:'Plásmido',emoji:'🔀',fn:'Molécula de ADN extracromosomal, circular y autorreplicante. Porta genes de ventaja adaptativa.',loc:'Citoplasma procariota (y algunos eucariotas).',struct:'ADN circular bicatenario de 1–200 kb. Sin histonas.',proc:'Replicación independiente del cromosoma. Transferencia por conjugación bacteriana.',diff:'Procariotas y algunos hongos. Ausente normalmente en células animales y vegetales.',path:'Plásmidos de resistencia (plasmidio R) transmiten resistencia antibiótica entre bacterias.',cur:'La biotecnología usa plásmidos para insertar genes de interés. Así se produce insulina humana en E. coli.'},
  ribosome70s:{name:'Ribosoma 70S',emoji:'⚫',fn:'Síntesis de proteínas en procariotas.',loc:'Libre en el citoplasma procariota.',struct:'Subunidades 30S (ARNr 16S) y 50S (ARNr 5S, 23S).',proc:'Traducción acoplada a transcripción. Polirribosomas frecuentes.',diff:'70S en procariotas vs 80S en eucariotas. Esta diferencia es diana de antibióticos.',path:'Objetivo de: aminoglucósidos, cloranfenicol, eritromicina, tetraciclina.',cur:'La subunidad 50S contiene el centro peptidil-transferasa, que es una ribozima (ARN catalítico).'},
  ribosome70s2:{name:'Ribosoma 70S',emoji:'⚫',fn:'Síntesis proteica procariota. Objetivo de antibióticos.',loc:'Citoplasma procariota.',struct:'30S + 50S = 70S.',proc:'Traducción simultánea a transcripción.',diff:'Más pequeño que el eucariota 80S.',path:'Diana de antibióticos bactericidas y bacteriostáticos.',cur:'Traducción a ~15–20 aminoácidos por segundo en procariotas.'},
  pili:{name:'Pili / Fimbrias',emoji:'🕷️',fn:'Apéndices proteicos para adhesión a sustratos y otros organismos. Pili sexuales transfieren plásmidos.',loc:'Superficie celular bacteriana.',struct:'Polímero de pilina. Longitud variable.',proc:'Adhesión (colonización de hospedero), conjugación bacteriana (transferencia de ADN).',diff:'Exclusivo de procariotas.',path:'Pili tipo I y P en E. coli → infecciones urinarias. Pili de N. gonorrhoeae → gonorrea.',cur:'Los pili son tan delgados (~7 nm) que solo son visibles al microscopio electrónico.'},
  flagella:{name:'Flagelo Bacteriano',emoji:'🚩',fn:'Propulsión y motilidad. Permite a la bacteria desplazarse en medios líquidos (quimiotaxis).',loc:'Superficie de la célula bacteriana.',struct:'Filamento (flagelina), gancho de unión y motor basal rotatorio anclado en la membrana. Rotación hasta 1.500 rpm.',proc:'Rotación antihoraria → nado recto. Horaria → tumbo (cambio de dirección).',diff:'Flagelo bacteriano (rotatorio, flagelina) ≠ eucariota (microtubular, axonema 9+2).',path:'H. pylori usa flagelos para penetrar el mucus gástrico y causar úlceras.',cur:'El flagelo bacteriano se autoensambla: la flagelina se exporta a través del canal hueco del propio filamento.'},
  cell_wall_p:{name:'Pared Celular Bacteriana',emoji:'🛡️',fn:'Protección mecánica, mantenimiento de forma y resistencia a la presión osmótica.',loc:'Exterior de la membrana plasmática bacteriana.',struct:'Peptidoglicano (mureína). Gram+: pared gruesa. Gram−: pared delgada + membrana externa adicional.',proc:'Síntesis de peptidoglicano (diana de penicilina y vancomicina).',diff:'Bacteria: peptidoglicano. Planta: celulosa. Hongo: quitina. Animal: ninguna.',path:'Antibióticos β-lactámicos bloquean síntesis de pared → lisis bacteriana.',cur:'La tinción de Gram diferencia bacterias según el grosor de su pared: Gram+ retiene violeta de genciana.'},
  membrane_p:{name:'Membrana Plasmática (Bacteria)',emoji:'🌐',fn:'Barrera selectiva y sede de la respiración celular (ausencia de mitocondrias).',loc:'Interior de la pared celular bacteriana.',struct:'Bicapa fosfolipídica sin colesterol (contiene hopanoides). Proteínas de cadena respiratoria.',proc:'Transporte de nutrientes, respiración aeróbica/anaeróbica, síntesis de ATP.',diff:'Cumple funciones adicionales respecto a la eucariota: es la sede de la respiración.',path:'Polimixinas desestabilizan la membrana bacteriana → bactericidas.',cur:'La membrana interna mitocondrial es homóloga a la membrana bacteriana: evidencia de endosimbiosis.'},
  capsule:{name:'Cápsula',emoji:'🔵',fn:'Capa mucilaginosa externa que protege a la bacteria de la fagocitosis y la desecación. Factor de virulencia.',loc:'Exterior de la pared celular.',struct:'Polisacáridos (mayormente). En Bacillus anthracis: proteínas de D-ácido glutámico.',proc:'Adhesión, evasión del sistema inmune, formación de biofilm.',diff:'Exclusivo de algunas bacterias.',path:'Streptococcus pneumoniae con cápsula es virulento; sin cápsula, avirulento. Causa neumonía y meningitis.',cur:'La cápsula fue clave en el experimento de Griffith (1928), que demostró la transformación bacteriana.'},
  hepato_membrane:{name:'Membrana Hepatocítica',emoji:'🌐',fn:'Regula el tráfico de moléculas entre la sangre (espacio de Disse) y el hepatocito. Tiene tres dominios funcionales: sinusoidal, lateral y canalicular.',loc:'Límite externo del hepatocito. El dominio sinusoidal da al espacio perisinusoidal (Disse).',struct:'Bicapa fosfolipídica con asimetría de dominios. Sinusoidal: NTCP, OATP1B1/1B3. Canalicular: BSEP, MRP2.',proc:'Captación de ácidos biliares y fármacos (dominio sinusoidal). Secreción de bilis y metabolitos conjugados (dominio canalicular).',diff:'A diferencia de otras células epiteliales, el hepatocito tiene dominio sinusoidal en contacto con sangre fenestrada (no barrera continua).',path:'Mutaciones en BSEP → colestasis intrahepática familiar. Mutaciones en MRP2 → síndrome de Dubin-Johnson.',cur:'El endotelio sinusoidal hepático tiene fenestraciones de 100–200 nm: permite el paso directo de lipoproteínas al hepatocito.'},
  nucleus_h:{name:'Núcleo Hepatocítico',emoji:'🟣',fn:'Control genético. Alta transcripción de genes de albúmina y factores de coagulación. Los hepatocitos adultos son frecuentemente binucleados o poliploides.',loc:'Centro del hepatocito. 25–30% son binucleados en el adulto.',struct:'Núcleo grande (8–10 µm). Cromatina laxa (activa). Nucléolo prominente. Envoltura nuclear con poros.',proc:'Alta actividad transcripcional (síntesis de proteínas plasmáticas). Pliploidía progresiva: 2n→4n→8n con la edad.',diff:'Único entre células adultas: hasta el 80% de los hepatocitos son poliploides, lo que aumenta capacidad biosintética.',path:'La hepatitis viral y el carcinoma hepatocelular afectan directamente al núcleo de los hepatocitos.',cur:'El hígado puede regenerar hasta el 70% de su masa: los hepatocitos tienen capacidad proliferativa excepcional.'},
  nucleolus_h:{name:'Nucléolo Hepático',emoji:'🔵',fn:'Fábrica de ribosomas 80S. Excepcionalmente activo por la alta demanda de síntesis de proteínas secretadas (albúmina: 12 g/día, factores de coagulación).',loc:'Interior del núcleo hepatocítico. Puede haber 1–3 nucléolos por núcleo.',struct:'Sin membrana. Componente fibrilar + granular. Asociado a regiones NOR del ADN ribosmico.',proc:'Síntesis de ARNr 45S, procesamiento, ensamblado de subunidades 40S y 60S, exportación al citoplasma.',diff:'El nucléolo hepático es proporcionalmente más grande y activo que en la mayoría de células somáticas.',path:'La cirrosis hepática reduce el nucléolo por pérdida de capacidad biosintética del hepatocito.',cur:'El hepatocito sintetiza prácticamente todas las proteínas del plasma sanguíneo, excepto anticuerpos.'},
  mito_h1:{name:'Mitocondria Hepática',emoji:'🔴',fn:'Central energética. El hepatocito contiene hasta 2.000 mitocondrias (20–25% del volumen celular), necesarias para el enorme gasto energético del metabolismo hepático.',loc:'Distribuidas en el citoplasma. Abundantes near el REL y peroxisomas.',struct:'Doble membrana, crestas muy desarrolladas, matriz densa. ADNmt circular y ribosomas 70S.',proc:'Ciclo de Krebs, β-oxidación parcial de ácidos grasos, cetogénesis, gluconeogénesis, cadena respiratoria.',diff:'Las mitocondrias hepáticas tienen alta actividad de β-oxidación, a diferencia de las musculares que priorizan ATP para contracción.',path:'NAFLD: las mitocondrias hepáticas muestran morfología anormal y disfunción en el hígado graso.',cur:'El hígado consume ~20% de todo el oxígeno del cuerpo en reposo, a pesar de representar solo el 2% del peso corporal.'},
  mito_h2:{name:'Mitocondria Hepática (2)',emoji:'🔴',fn:'Segunda mitocondria del hepatocito. Participa en cetogénesis (síntesis de cuerpos cetónicos en ayuno) y en la oxidación del etanol.',loc:'Citoplasma hepatocítico.',struct:'Doble membrana, crestas, matriz con enzimas del ciclo de Krebs y β-oxidación.',proc:'β-oxidación de ácidos grasos → acetil-CoA → cuerpos cetónicos. Oxidación de etanol vía ALDH.',diff:'En hepatocitos, la mitocondria alberga el ciclo de la urea (CPS1 en la matriz).',path:'El etanol crónico daña la membrana interna mitocondrial → disfunción energética → esteatosis alcohólica.',cur:'La cetogénesis hepática provee el 70% de la energía cerebral como cuerpos cetónicos en ayuno prolongado.'},
  er_rough_h:{name:'Retículo ER Rugoso Hepático',emoji:'🟠',fn:'Síntesis masiva de proteínas secretadas. El hepatocito produce >20 g de proteínas plasmáticas por día: albúmina, fibrinógeno, protrombina, factores V, VII, IX, X.',loc:'Red perinuclear extensa. Conectado con la envoltura nuclear.',struct:'Cisternas aplanadas con ribosomas. Lumen con chaperonas (BiP/GRP78, calreticulina).',proc:'Traducción co-traduccional de proteínas secretadas. N-glicosilación inicial. Control de calidad por BiP.',diff:'El RER hepático es uno de los más extensos del organismo, comparable al de las células acinares pancreáticas.',path:'Estrés del RE hepático → UPR → activación de IRE1α/PERK → apoptosis hepatocítica en esteatohepatitis.',cur:'El hepatocito sintetiza 12 g de albúmina por día, la proteína más abundante del plasma humano (3.5–5 g/dL).'},
  er_smooth_h:{name:'Retículo ER Liso (REL) Hepático',emoji:'🟡',fn:'Detoxificación de fármacos y xenóbiotics (citocromo P450), síntesis de colesterol y ácidos biliares, metabolismo de lípidos.',loc:'Red tubular extensa en el citoplasma. Se hipertrofia con exposición crónica a fármacos.',struct:'Membrana tubular sin ribosomas. Contiene el sistema citocromo P450 (CYP3A4, CYP2D6, etc.).',proc:'Reacciones de fase I (oxidación, CYP450). Síntesis de colesterol (HMG-CoA reductasa). Síntesis de ácidos biliares.',diff:'El REL hepático es único en contener la mayor batería de enzimas de biotransformación (>50 isoformas CYP450).',path:'La inducción del REL por fármacos (fenobarbital, rifampicina) aumenta la tolerancia y las interacciones farmacológicas.',cur:'El citocromo CYP3A4 metaboliza el 50% de todos los fármacos disponibles en el mercado. Está en el REL hepático.'},
  golgi_h:{name:'Aparato de Golgi Hepático',emoji:'🟤',fn:'Procesamiento, glicosilación y empaquetado de proteínas secretadas (albúmina, fibrinógeno) y lipoproteínas (VLDL, HDL). Centro de tráfico vesicular hepático.',loc:'Próximo al núcleo y al RER. Múltiples pilas (dictiosomas).',struct:'4–6 cisternas apiladas. Cara cis (recibe de RER) y cara trans (envía vesículas secretoras).',proc:'O-glicosilación, fosforilación de proteínas plasmáticas. Ensamblado final de VLDL con apoB-100. Secreción constitutiva.',diff:'El Golgi hepático tiene actividad extraordinaria en lipoproteínas: ensambla y secreta VLDL (~50 µm/día).',path:'Defectos en el Golgi → enfermedades CDG tipo II. Acumulación de VLDL defectuosas → esteatosis hepática.',cur:'El hígado secreta 50–100 mg de colesterol como VLDL por día hacia la sangre, regulando el colesterol circulante.'},
  lysosome_h:{name:'Lisosoma Hepático',emoji:'🟢',fn:'Degradación de organíulos dañados (autofagia), lipoproteínas captadas, glucógeno (glicofagia) y gotas lipídicas (lipofagia) en ayuno.',loc:'Citoplasma. Abundantes cerca del polo canalicular.',struct:'Vesícula con >50 hidrolasas ácidas. pH interno 4.5–5. Receptor M6P para targeting.',proc:'Macroautofagia (recambio de mitocondrias viejas). Lipofagia (degradación autofágica de gotas lipídicas). Glicogenólisis lisosomal.',diff:'En hepatocitos la lipofagia es fundamental: los lisosomas degradan gotas lipídicas directamente. No ocurre igual en otros tejidos.',path:'Enfermedad de Pompe: deficiencia de α-glucosidasa lisosomal → acumulación de glucógeno → daño hepático y muscular.',cur:'La autofagia hepática elimina el 1–2% de las proteínas celulares por hora. Es la forma en que el hígado recicla sus organíulos.'},
  peroxisome_h:{name:'Peroxisoma Hepático',emoji:'🟡',fn:'β-oxidación de ácidos grasos de cadena muy larga (AGCML, >C22), síntesis de ácidos biliares y plasmalógenos. Detoxificación de H₂O₂ por catalasa.',loc:'Abundantes en el citoplasma hepático (400–600 por hepatocito). Asociados al REL.',struct:'Vesícula de membrana simple. Core con catalasa y enzimas de oxidación de AGCML. Sin genoma propio.',proc:'β-oxidación de AGCML (VLCFA) → acil-CoA de cadena corta → mitocondria. Síntesis de ácido cólico y quenodesoxicólico.',diff:'Hígado y riñón: peroxisomas más activos en β-oxidación de AGCML. Células musculares: β-oxidación solo mitocondrial.',path:'Síndrome de Zellweger: déficit de biogénesis peroxisomal → acumulación de AGCML → daño hepático neonatal grave.',cur:'Los peroxisomas hepáticos sintetizan el 100% de los ácidos biliares primarios del organismo (cólico y quenodesoxicólico).'},
  glycogen:{name:'Glucógeno',emoji:'🍬',fn:'Reserva energética de glucosa en el hepatocito. El hígado almacena 75–100 g de glucógeno para mantener la glucemia en periodos de ayuno corto.',loc:'Citoplasma hepatocítico como gránulos α (rosetas de partículas β). Muy abundante postprandial.',struct:'Polisacárido ramificado de glucosa (enlace α-1,4 y ramas α-1,6). Gránulos β: 20–40 nm. Rosetas α: 200 nm.',proc:'Síntesis: glucosa-6-P → UDP-glucosa → glucógeno (glucógeno sintasa, activada por insulina). Degradación: glucógeno fosforilasa (activada por glucagón/adrenalina).',diff:'Músculo: glucógeno para uso local (no libera glucosa a sangre). Hígado: glucógeno para mantener glucemia sistémica.',path:'Glucogenosis tipo I (von Gierke): déficit de glucosa-6-fosfatasa → acumulación masiva de glucógeno → hepatomegalia.',cur:'Tras 24 h de ayuno, el glucógeno hepático se agota completamente. El hígado entonces usa la gluconeogénesis.'},
  lipid_drop_h:{name:'Gota Lipídica Hepática',emoji:'🟡',fn:'Reserva de triacilgliceroles y ésteres de colesterol. Su acumulación excesiva produce esteatosis hepática (hígado graso).',loc:'Citoplasma. En contacto con el REL, mitocondrias y peroxisomas.',struct:'Núcleo de TAG y ésteres de colesterol. Monolamina de fosfolipidos. Proteínas coat: PLIN2 (perilinina 2) principalmente en hígado.',proc:'Síntesis: esterificación de ácidos grasos libres o lipogénesis de novo. Movilización: lipasas (ATGL, HSL) → ácidos grasos → β-oxidación o VLDL.',diff:'Las gotas lipídicas hepáticas se asocian a PLIN2, mientras que en adipocitos predomina PLIN1. Diferencia en regulación de lipólisis.',path:'Esteatosis (>5% lípidos en hepatocitos) → esteatohepatitis no alcohólica (NASH) → cirrosis → carcinoma hepatocelular.',cur:'El NAFLD afecta al 25% de la población mundial adulta y es la enfermedad hepática más frecuente.'},
  bile_canaliculus:{name:'Canalículo Biliar',emoji:'🟩',fn:'Canal microscópico formado por la membrana apical de hepatocitos adyacentes. Recoge y transporta la bilis sintetizada hacia los canaliculos interlobulillares.',loc:'Surco formado entre las membranas apicales de 2–3 hepatocitos adyacentes. Sellado por uniones ocluyentes.',struct:'Luz de 0.5–1 µm. Microvilli en la superficie luminal. Transportadores BSEP, MRP2, MDR3.',proc:'Secreción activa de ácidos biliares (BSEP), bilirrubina conjugada (MRP2), fosfolipidos (MDR3). Flujo 0.6 L bilis/día.',diff:'Exclusivo de hepatocitos. Las células biliares (colangiocitos) modifican la composición biliar, pero no la secretan.',path:'Colestasis: fallo en secreción biliar → acumulación de sales biliares tóxicas en hepatocitos → daño celular.',cur:'El canalicülo biliar mide 0.5–1 µm de diámetro, pero el hígado produce 600–1200 mL de bilis al día.'},
  // ── FUNGI ──
  chitin_wall:{name:'Pared de Quitina',emoji:'🛡️',fn:'Soporte estructural rígido y protección mecánica. La quitina es el segundo polisacárido más abundante en la naturaleza.',loc:'Capa más externa de la célula fúngica, exterior a la membrana plasmática.',struct:'Microfibras de β-1,4-N-acetilglucosamina entretejidas con glucanos (β-1,3 y β-1,6). Matriz proteica.',proc:'Síntesis de quitina por la quitina sintasa. Remodelado dinámico durante crecimiento y reproducción.',diff:'Hongos: quitina. Plantas: celulosa. Bacterias: peptidoglicano. Animales: ninguna.',path:'La quitina es diana antifúngica: equinocandinas inhiben β-glucano sintasa.',cur:'Las equinocandinas son el antifúngico más nuevo. Los insectos también tienen exoesqueleto de quitina.'},
  membrane_f:{name:'Membrana con Ergosterol',emoji:'🌐',fn:'Barrera selectiva fúngica. El ergosterol reemplaza al colesterol animal como estabilizador de fluidez membrana.',loc:'Límite externo del citoplasma, bajo la pared de quitina.',struct:'Bicapa fosfolipídica con ergosterol (~25% de los lípidos). Proteínas integrales y periféricas.',proc:'Transporte de nutrientes, señalización. Sede de la cadena respiratoria en levaduras anaerobias.',diff:'Animal/vegetal: colesterol. Hongo: ergosterol. Bacteria: hopanoides.',path:'Anfotericina B y azoles actúan sobre ergosterol. Anfotericina forma poros en membrana fúngica.',cur:'El ergosterol es precursor de vitamina D₂. La luz UV lo convierte en ergocalciferol.'},
  nucleus_f:{name:'Núcleo Fúngico',emoji:'🟣',fn:'Centro de control genético. Contiene el ADN diploide o haploide según el estado del ciclo vital del hongo.',loc:'Centro del soma fúngico (levadura) o en los compartimentos hifales.',struct:'Envoltura nuclear con poros. ADN compactado con histonas. Nucléolo presente.',proc:'Mitosis cerrada (sin ruptura de la envoltura nuclear, única en hongos). Meiosis para reproducción sexual.',diff:'Los hongos realizan mitosis cerrada: el huso se forma dentro del núcleo intacto.',path:'Mutaciones en genes de reparación del ADN fúngico → mayor tasa mutacional y adaptación a antifúngicos.',cur:'Saccharomyces cerevisiae fue el primer eucariota en secuenciar su genoma completo (1996).'},
  nucleolus_f:{name:'Nucléolo Fúngico',emoji:'🔵',fn:'Fábrica de ribosomas 80S. Esencial para la biosíntesis de ARNr y el ensamblado de subunidades ribosómicas.',loc:'Interior del núcleo fúngico.',struct:'Sin membrana propia. Centro fibrilar denso (FC), componente fibrilar denso (DFC) y componente granular (GC).',proc:'Transcripción de ADNr por ARN Pol I, procesamiento del pre-ARNr 35S (levaduras). Exportación de subunidades.',diff:'Idéntico funcionalmente al de células animales. El pre-ARNr es 35S en levaduras vs 45S en mamíferos.',path:'Inhibidores de ARN Pol I como CX-5461 muestran actividad antifúngica selectiva.',cur:'El nucléolo fúngico persiste durante la mitosis cerrada, a diferencia de las células animales.'},
  mito_f:{name:'Mitocondria Fúngica',emoji:'🔴',fn:'Producción de ATP por respiración aeróbica. Clave en el metabolismo del etanol en levaduras.',loc:'Citoplasma. En levaduras, forman una red tubular dinámica (reticulo mitocondrial).',struct:'Doble membrana. Crestas. ADN mitocondrial circular. Ribosomas 70S propios.',proc:'Ciclo de Krebs. Cadena respiratoria. Fermentación alcohólica cuando O₂ es limitado.',diff:'Levaduras son aerobias facultativas: alternan respiración y fermentación (efecto Pasteur).',path:'Mutaciones en ADN mitocondrial fúngico generan colonias "petite" (pequeñas) en Saccharomyces.',cur:'Las levaduras producen etanol y CO₂ fermentando glucosa: base de pan, cerveza y vino.'},
  er_f:{name:'Retículo ER Fúngico',emoji:'🟠',fn:'Síntesis y plegamiento de proteínas de membrana y secretadas. Inicio de la glicosilación N-ligada.',loc:'Red perinuclear, conectada a la envoltura nuclear.',struct:'Cisternas aplanadas con ribosomas adheridos. Lumen con chaperonas (BiP/Kar2p en levaduras).',proc:'Traducción co-traduccional. N-glicosilación inicial. Control de calidad de proteínas.',diff:'Homólogo al RER animal. Los hongos tienen una respuesta UPR (unfolded protein response) activa.',path:'Estrés del RE fúngico → UPR → sobreexpresión de genes de virulencia en patógenos.',cur:'El RE de levaduras se conecta con el núcleo en la mitosis cerrada, participando en la segregación.'},
  golgi_f:{name:'Aparato de Golgi Fúngico',emoji:'🟤',fn:'Modificación, clasificación y empaque de proteínas y lípidos. En levaduras existe como cisternas dispersas.',loc:'Próximo al RE. En levaduras, cisternas individuales (no apiladas como en células animales).',struct:'Cisternas dispersas o ligeramente apiladas. Cara cis y trans definidas funcionalmente.',proc:'O-glicosilación de proteínas (muy extensa en hongos). Formación de vesículas secretoras.',diff:'El Golgi de levaduras no forma pilas. En hongos filamentosos sí pueden apilarse.',path:'La hipermanosílación de proteínas fúngicas es parte de su respuesta inmunogénica.',cur:'Los hongos pueden O-manosilar proteínas, un proceso inusual ausente en células animales.'},
  vacuole_f:{name:'Vacuola Fúngica',emoji:'💧',fn:'Equivalente al lisosoma animal y la vacuola vegetal. Degradación, almacenamiento de iones y regulación osmótica.',loc:'Gran orgánulo central en células fúngicas maduras.',struct:'Membrana llamada tonoplasto fúngico. Hidrolasas ácidas. pH interno ~6. Fosfato, K⁺, aminoácidos.',proc:'Autofagia, degradación de proteínas dañadas, almacenamiento de polifosfato.',diff:'Combina funciones del lisosoma animal y la vacuola vegetal. Clave en la homeostasis del pH.',path:'Defectos vacuolares en hongos patógenos reducen su virulencia.',cur:'Las vacuolas fúngicas almacenan hasta el 80% del polifosfato celular, crucial para el metabolismo del P.'},
  ribosome_f:{name:'Ribosoma 80S Fúngico',emoji:'⚫',fn:'Síntesis de proteínas mediante traducción del ARNm. Idéntico en tamaño al eucariota animal.',loc:'Libre en citoplasma o adherido al RE rugoso.',struct:'Subunidades 40S y 60S = 80S total. ARNr y proteínas ribosómicas.',proc:'Traducción: inicio, elongación, terminación.',diff:'Igual al ribosoma 80S eucariota. Diferente al 70S procariota. Por eso antibióticos no afectan hongos.',path:'La ciclohexamida inhibe ribosomas 80S fúngicos y eucariotas. No es selectiva → tóxica en humanos.',cur:'La similitud del ribosoma fúngico con el humano dificulta el desarrollo de antifúngicos selectivos.'},
  woronin:{name:'Cuerpo de Woronin',emoji:'🔷',fn:'Organelo exclusivo de hongos filamentosos Ascomycetes. Tapona los poros de los septos ante daño celular.',loc:'Cerca de los poros septales en hifas de Ascomycetes.',struct:'Matriz proteica cristalina de HEX-1 (hexagons). Membrana simple.',proc:'Ante rotura de hifa, los cuerpos de Woronin migran y taponan el poro para prevenir pérdida de citoplasma.',diff:'Exclusivo de Ascomycetes. Ausente en Basidiomycetes, levaduras y células animales/vegetales.',path:'Sin cuerpos de Woronin → las hifas dañadas sangran y mueren → mayor susceptibilidad a daño.',cur:'Descubiertos en 1864 por Woronin. Su función como tapón septale no se entendió hasta el año 2000.'},
  lipid_drop:{name:'Gota Lipídica',emoji:'🟡',fn:'Reserva energética y fuente de lípidos de membrana. Esencial en levaduras bajo estrés nutricional.',loc:'Citoplasma, en contacto con el RE.',struct:'Núcleo de triacilgliceroles y ésteres de esterol. Monolámina de fosfolípidos con proteínas (perilipinas fúngicas).',proc:'Síntesis de lípidos de reserva en abundancia de nutrientes. Lipólisis por lipasas en ayuno.',diff:'Presentes en animales, plantas y hongos. En hongos su tamaño aumenta dramáticamente en fase estacionaria.',path:'Acumulación excesiva de gotas lipídicas en levaduras → reducción de producción de etanol.',cur:'Las gotas lipídicas son la fuente de lípidos para la síntesis de membranas durante la división.'},
  hyphal_pore:{name:'Septo con Poro',emoji:'🔗',fn:'Tabique que divide compartimentos hifales, con poro central que permite comunicación citoplasmática.',loc:'Pared transversal entre células hifales en hongos filamentosos.',struct:'Pared de quitina y glucanos. Poro central de 0.05–0.5 µm. En Ascomycetes: tapón de Woronin.',proc:'Flujo de citoplasma, orgánulos y nutrientes entre células. Permite la sincronización del crecimiento.',diff:'Ascomycetes: poro simple tapado por Woronin. Basidiomycetes: poro en barril (dolipore) más complejo.',path:'Virus de hongos (micovirosis) se propagan entre células a través de los poros septales.',cur:'En hongos dikarióticos (con dos núcleos), los septos permiten que ambos núcleos coexistan generaciones enteras.'},
  // ── NEURON ──
  neuron_membrane:{name:'Membrana Neuronal',emoji:'🌐',fn:'Genera y propaga potenciales de acción. Altamente especializada con canales iónicos voltaje-dependientes.',loc:'Límite externo de todo el cuerpo neuronal y sus prolongaciones.',struct:'Bicapa lipídica con alta densidad de canales Na⁺, K⁺, Ca²⁺ y Cl⁻. Proteínas de anclaje al citoesqueleto.',proc:'Potencial en reposo (-70 mV), despolarización, repolarización. Transmisión del impulso nervioso.',diff:'Excitable: responde con cambios eléctricos. La mayoría de células no generan potenciales de acción.',path:'Esclerosis múltiple: desmielinización; Epilepsia: hiperexcitabilidad; SLA: degeneración motoneuronas.',cur:'Una neurona puede recibir hasta 200.000 sinapsis simultáneas sobre su membrana.'},
  soma_nucleus:{name:'Núcleo del Soma',emoji:'🟣',fn:'Control genético de la neurona. Altamente activo en transcripción dado el alto metabolismo neuronal.',loc:'Centro del soma (cuerpo celular) neuronal.',struct:'Gran núcleo esférico, cromatina laxa (activa). Nucléolo prominente por alta demanda de ribosomas.',proc:'Transcripción activa de genes neuronales. Síntesis de ARNm que se transporta a lo largo del axón.',diff:'Las neuronas son postmitóticas (no se dividen). Su núcleo está permanentemente en interfase.',path:'Daño al ADN neuronal es irreparable (no hay mitosis). Acumulación de daño → envejecimiento neuronal.',cur:'Las neuronas expresan ~80% del genoma, más que cualquier otro tipo celular del organismo.'},
  nucleolus_n:{name:'Nucléolo Neuronal',emoji:'🔵',fn:'Fábrica de ribosomas 80S. Especialmente grande en neuronas por la altísima demanda de síntesis proteica.',loc:'Interior del núcleo del soma.',struct:'Sin membrana propia. Centro fibrilar + componente fibrilar denso + componente granular.',proc:'Transcripción del ADNr, procesamiento del pre-ARNr 45S, exportación de subunidades ribosómicas.',diff:'El nucléolo neuronal es proporcionalmente mayor que en otras células por su alta actividad.',path:'Reducción del nucléolo neuronal es marcador temprano en enfermedades neurodegenerativas como Parkinson.',cur:'La neurona motora de la médula tiene el nucléolo más grande de todas las células del cuerpo humano.'},
  nissl_body:{name:'Cuerpos de Nissl',emoji:'🟠',fn:'Sitios de síntesis masiva de proteínas. Son cisternas del RE rugoso organizadas en pilas.',loc:'Soma y dendritas (ausente en axón y cono axónico).',struct:'Pilas de RER con ribosomas. Se tiñen con azul de toluidina. Visibles al microscopio óptico.',proc:'Síntesis de proteínas estructurales y funcionales del axón: neurotransmisores, enzimas.',diff:'Característica casi exclusiva de neuronas. Alta densidad de RER visible histológicamente.',path:'Cromatólisis: disolución de los cuerpos de Nissl tras lesión axonal (respuesta regenerativa).',cur:'Franz Nissl los describió en 1894. Son tan abundantes que hacen al soma neuronal muy basófilo.'},
  mito_n:{name:'Mitocondria Axonal',emoji:'🔴',fn:'Producción de ATP local para la bomba Na⁺/K⁺ ATPasa y la maquinaria sináptica. Crítica en nodos de Ranvier.',loc:'Distribuidas a lo largo del axón, concentradas en terminales sinápticos y nodos de Ranvier.',struct:'Doble membrana, crestas. En axones: forma alargada y se mueven activamente por el axón.',proc:'ATP para la bomba Na⁺/K⁺, la exocitosis de vesículas sinápticas y el movimiento de motores moleculares.',diff:'En neuronas deben transportarse desde el soma hasta el terminal: transporte axonal anterógrado.',path:'Disfunción mitocondrial axonal → Parkinson, Alzheimer, SLA, neuropatía periférica.',cur:'El transporte mitocondrial a lo largo del axón puede recorrer hasta 1 metro en neuronas motoras.'},
  axon:{name:'Axón',emoji:'⚡',fn:'Conducción del impulso nervioso desde el soma hasta la terminal sináptica. Puede medir hasta 1 metro.',loc:'Prolongación única del soma. Emerge del cono axónico.',struct:'Microtúbulos orientados (+) hacia la terminal. Neurofilamentos. Cubierto por vaina de mielina en axones mielinizados.',proc:'Conducción saltatoria del potencial de acción (mielinizado) o continua (amielínico).',diff:'Un axón por neurona (ley de Cajal). Las dendritas son múltiples y más cortas.',path:'Lesión axonal → degeneración walleriana. SLA destruye axones motores.',cur:'El axón del nervio ciático puede medir >1 m. Su impulso viaja a 70-120 m/s en fibras mielinizadas.'},
  myelin:{name:'Vaina de Mielina',emoji:'🏮',fn:'Acelera dramáticamente la conducción del impulso nervioso (conducción saltatoria).',loc:'Envuelve segmentalmente el axón. Producida por células de Schwann (SNP) u oligodendrocitos (SNC).',struct:'Capas de membrana plasmática enrolladas (80% lípidos, 20% proteínas). Proteína básica de mielina (MBP).',proc:'El impulso salta entre nodos de Ranvier (sin mielina). Velocidad 70–120 m/s vs 0.5–2 m/s sin mielina.',diff:'SNP: una célula de Schwann mieliniza un segmento de un axón. SNC: un oligodendrocito → 50 segmentos.',path:'Esclerosis múltiple: desmielinización autoinmune del SNC. Guillain-Barré: del SNP.',cur:'La mielina tiene el ratio lípido/proteína más alto de cualquier membrana biológica conocida.'},
  dendrite:{name:'Dendritas',emoji:'🌿',fn:'Reciben y procesan señales sinápticas de miles de neuronas presinápticas. Integración neuronal.',loc:'Múltiples prolongaciones del soma que se ramifican extensamente.',struct:'Microtúbulos con orientación mixta. Espinas dendríticas (lugar de sinapsis excitatorias). Ribosomas locales.',proc:'Integración espacial y temporal de señales excitatorias e inhibitorias (EPSP e IPSP).',diff:'Múltiples por neurona (vs un axón). Conducen señales hacia el soma. Los axones, desde el soma.',path:'Reducción de espinas dendríticas en Alzheimer, autismo y esquizofrenia.',cur:'Las espinas dendríticas cambian de morfología en minutos: base celular del aprendizaje y la memoria.'},
  synapse:{name:'Terminal Sináptico',emoji:'⚡',fn:'Liberación de neurotransmisores por exocitosis. Convierte el impulso eléctrico en señal química.',loc:'Extremo del axón. Forma el botón sináptico presináptico.',struct:'Vesículas sinápticas (40 nm) con neurotransmisores. Ca²⁺ dispara la fusión. Maquinaria SNARE.',proc:'Exocitosis Ca²⁺-dependiente. Reciclaje de vesículas por endocitosis (clatrina).',diff:'Sinapsis química (la mayoría) vs eléctrica (gap junctions, más rápida pero sin amplificación).',path:'Botulismo: toxina inhibe SNARE → no hay exocitosis → parálisis flácida.',cur:'Una neurona libera neurotransmisor en 0.5 ms tras llegar el impulso. La cuántica sináptica = 1 vesícula.'},
  axon_hillock:{name:'Cono Axónico',emoji:'🔺',fn:'Zona generadora del potencial de acción. Alta densidad de canales Na⁺ voltaje-dependientes.',loc:'Unión entre el soma y el axón. Zona de iniciación del impulso.',struct:'Sin RER ni ribosomas. Alta densidad de canales Nav1.1–Nav1.6. Citoplasma denso en microtúbulos.',proc:'Integra todas las señales del soma. Si supera el umbral (~-55 mV) genera el potencial de acción.',diff:'Estructura única de las neuronas. Define la dirección de propagación del impulso.',path:'Mutaciones en canales Nav del cono axónico → epilepsias hereditarias y síndromes de dolor.',cur:'El cono axónico es la "zona de decisión" neuronal: filtra todo el ruido para generar o no el impulso.'},
  golgi_n:{name:'Aparato de Golgi Neuronal',emoji:'🟤',fn:'Modificación y distribución de proteínas hacia distintas partes de la neurona: dendritas, axón, sinapsis.',loc:'Región paranuclear del soma, con extensiones en dendritas grandes.',struct:'Pilas de cisternas bien organizadas. Asociado a gránulos de secreción y vesículas de transporte.',proc:'Procesamiento de receptores de neurotransmisores, canales iónicos, proteínas de sinapsis.',diff:'El Golgi neuronal puede ramificarse hacia las dendritas (outposts de Golgi).',path:'Fragmentación del Golgi neuronal es marcador temprano de apoptosis y de neurodegeneración.',cur:'Las neuronas tienen "Golgi satélites" en dendritas que procesan proteínas localmente.'},
  er_n:{name:'RE Neuronal',emoji:'🟠',fn:'Síntesis de proteínas de membrana, receptores y canales iónicos. Fuente de Ca²⁺ para señalización.',loc:'Perinuclear y extendiéndose por soma y dendritas. Fragmentos llegan al axón.',struct:'RER (cuerpos de Nissl) y REL. El REL neuronal almacena Ca²⁺ y lo libera en señalización.',proc:'Síntesis de proteínas de membrana. Liberación de Ca²⁺ por InsP3R ante estímulo sináptico.',diff:'En dendritas hay RE liso que modula la señalización de Ca²⁺ en espinas dendríticas.',path:'Estrés del RE neuronal → acumulación de proteínas mal plegadas → Alzheimer, Parkinson.',cur:'El Ca²⁺ del RE neuronal puede amplificar localmente las señales sinápticas hasta 10 veces.'},
  // ── RBC ──
  rbc_membrane:{name:'Membrana Eritrocítica',emoji:'🌐',fn:'Límite deformable del eritrocito. Permite la deformación extrema para pasar por capilares de 2-3 µm.',loc:'Límite externo del glóbulo rojo.',struct:'Bicapa lipídica asimétrica + espectrina en red. Sin núcleo ni orgánulos. 120 días de vida.',proc:'Deformación reversible en capilares. Intercambio gaseoso pasivo. Reconocimiento inmune (grupos sanguíneos).',diff:'Sin núcleo, sin mitocondrias, sin síntesis proteica. Completamente diferenciado para transportar O₂.',path:'Esferocitosis hereditaria: defecto en espectrina → glóbulos frágiles y esféricos.',cur:'El eritrocito pasa 170.000 veces por el corazón en su vida. Cada paso comprime su diámetro a la mitad.'},
  hemoglobin:{name:'Hemoglobina',emoji:'🩸',fn:'Transporta O₂ desde pulmones hasta tejidos y CO₂ en sentido inverso. Proteína cuaternaria tetramérica.',loc:'Citoplasma del eritrocito. 270 millones de moléculas por glóbulo rojo.',struct:'4 subunidades (2α + 2β en adulto). Cada una con un grupo hemo (Fe²⁺). PM ~64.5 kDa.',proc:'Unión cooperativa de O₂ (curva sigmoide). Efecto Bohr: CO₂ y H⁺ reducen afinidad en tejidos.',diff:'HbA (adulto) vs HbF (fetal, mayor afinidad por O₂) vs HbS (drepanocitosis).',path:'Drepanocitosis: Glu→Val en posición 6 de la β-globina → HbS → polimerización → células en hoz.',cur:'La hemoglobina puede cargar 1.34 mL de O₂ por gramo. La sangre transporta 200 mL O₂/L.'},
  spectrin:{name:'Red de Espectrina',emoji:'🕸️',fn:'Andamiaje citoesquelético que da elasticidad y resistencia mecánica a la membrana eritrocítica.',loc:'Cara interna de la membrana plasmática del eritrocito.',struct:'Heterodímeros de α-espectrina y β-espectrina entrecruzados con actina y proteína 4.1. Red hexagonal.',proc:'Ancla proteínas integrales (banda 3, glicoforinas). Mantiene la bicóncavidad y la deformabilidad.',diff:'Citoesqueleto bidimensional único del eritrocito. Las células nucleadas tienen citoesqueleto tridimensional.',path:'Defectos en espectrina → esferocitosis, eliptocitosis hereditarias. Anemia hemolítica crónica.',cur:'La red de espectrina puede deformarse hasta 8 veces su tamaño natural y recuperarse sin daño.'},
  band3:{name:'Proteína Banda 3',emoji:'🔌',fn:'Transportador aniónico principal. Intercambia Cl⁻ por HCO₃⁻ (proceso vital para transporte de CO₂).',loc:'Membrana plasmática del eritrocito. ~10⁶ copias por célula.',struct:'Proteína integral de membrana, 14 segmentos transmembrana. Se ancla a la espectrina via anquirina.',proc:'Intercambio electroneutro de Cl⁻/HCO₃⁻ en 50 ms. Permite que el CO₂ viaje disuelto en plasma.',diff:'Equivalente funcional de los intercambiadores de aniones en otros tejidos, pero a velocidad extrema.',path:'Mutaciones en banda 3 → esferocitosis y anemia hemolítica. Objetivo de la malaria (Plasmodium).',cur:'Banda 3 es la proteína más abundante de la membrana eritrocítica: 25% de todas las proteínas.'},
  band3b:{name:'Proteína Banda 3 (2)',emoji:'🔌',fn:'Segunda copia del transportador aniónico Cl⁻/HCO₃⁻. Esencial para el transporte eficiente de CO₂.',loc:'Membrana plasmática del eritrocito.',struct:'Idéntica a Banda 3. Forma dímeros y tetrámeros en la membrana.',proc:'Intercambio aniónico. Se une a la hemoglobina desoxigenada en su dominio citosólico.',diff:'La unión de HbS desoxigenada a banda 3 es anómala → señalización de eriptosis.',path:'Su acumulación en la superficie como antígeno "banda 3 senescente" señala el glóbulo rojo para fagocitosis.',cur:'El dominio citosólico de banda 3 actúa como organizador del citoesqueleto periférico.'},
  glycophorin:{name:'Glicoforina A',emoji:'🍭',fn:'Proteína glicosilada de la membrana eritrocítica. Portadora de antígenos MN del grupo sanguíneo.',loc:'Membrana plasmática. ~10⁶ copias por eritrocito.',struct:'Proteína con dominio extracelular rico en ácido siálico. 1 segmento transmembrana.',proc:'Carga negativa del ácido siálico previene adhesión entre eritrocitos. Receptora de patógenos.',diff:'Única de eritrocitos en la proporción y glicosilación específica.',path:'Receptor del parásito Plasmodium falciparum para invasión del eritrocito (malaria).',cur:'El ácido siálico de glicoforinas genera el potencial zeta negativo que evita agregación eritrocítica.'},
  glycophorin2:{name:'Glicoforina C',emoji:'🍭',fn:'Ancla el citoesqueleto de espectrina a la membrana. Portadora del antígeno Gerbich.',loc:'Membrana plasmática del eritrocito.',struct:'Proteína transmembrana que interactúa con la proteína 4.1 y la actina del citoesqueleto.',proc:'Conexión estructural entre membrana y citoesqueleto. Mantiene la bicóncavidad.',diff:'Menos abundante que glicoforina A. Su deficiencia afecta la forma eritrocítica.',path:'Ausencia de glicoforina C → eliptocitosis hereditaria leve.',cur:'Los eritrocitos con deficiencia de glicoforina C son resistentes a la malaria por P. falciparum.'},
  ankyrin:{name:'Anquirina',emoji:'⚓',fn:'Proteína adaptadora que ancla la red de espectrina a la banda 3 integral de membrana.',loc:'Cara citosólica de la membrana eritrocítica.',struct:'Proteína de ~210 kDa con dominios de unión a banda 3, β-espectrina y proteína 4.2.',proc:'Conecta el citoesqueleto (espectrina) con la membrana (banda 3). Mantiene la arquitectura celular.',diff:'Presente en muchos tejidos, pero fundamental en eritrocitos para la arquitectura bidimensional.',path:'Mutaciones en anquirina son la causa más común de esferocitosis hereditaria en Europa.',cur:'La anquirina es la proteína "pegamento": sin ella, la membrana y el citoesqueleto se separan.'},
  carbonic_anh:{name:'Anhidrasa Carbónica II',emoji:'💨',fn:'Cataliza la conversión de CO₂ + H₂O ↔ HCO₃⁻ + H⁺ con enorme velocidad. Clave en transporte de CO₂.',loc:'Citoplasma del eritrocito. Altísima concentración: ~0.3 mg/mL.',struct:'Enzima de 29 kDa con ión Zn²⁺ en el sitio activo. Una de las enzimas más rápidas conocidas.',proc:'Hidrata CO₂ en HCO₃⁻ en tejidos. En pulmones, el proceso inverso libera CO₂ para exhalación.',diff:'La isoforma eritrocítica (CA-II) es la más activa. CA-IV está en la membrana de células endoteliales.',path:'Deficiencia de CA-II → acidosis, osteopetrosis y retraso mental.',cur:'CA-II cataliza 10⁶ reacciones/segundo. Sin ella, el transporte de CO₂ sería 13.000 veces más lento.'},
  biconcave:{name:'Forma Bicóncava',emoji:'🫧',fn:'La forma de disco bicóncavo maximiza la superficie de intercambio gaseoso y permite la deformación.',loc:'Morfología global del eritrocito maduro.',struct:'Disco plano de 6-8 µm de diámetro y 2 µm de grosor. Sin núcleo. Área superficial ~135 µm².',proc:'La concavidad bilateral disminuye la distancia de difusión del O₂. Permite deformación en capilares de 2 µm.',diff:'Exclusivo del eritrocito maduro. Los eritrocitos inmaduros (reticulocitos) son esféricos.',path:'En drepanocitosis la forma bicóncava se pierde → células en hoz que obstruyen capilares.',cur:'La forma bicóncava da 20-30% más de superficie que una esfera de igual volumen.'},
  // ── XYLEM ──
  secondary_wall:{name:'Pared Secundaria Lignificada',emoji:'🛡️',fn:'Refuerzo mecánico masivo. La lignina hace la pared impermeable e irreversiblemente rígida.',loc:'Depositada sobre la pared primaria en células xilemáticas maduras.',struct:'Celulosa + hemicelulosa + lignina (~25%). 3 capas (S1, S2, S3) con orientaciones de microfibrillas distintas.',proc:'Lignificación ocurre post-diferenciación. Irreversible: la célula muere al completar la pared secundaria.',diff:'Solo células de soporte y conductoras. Madera = xilema secundario con pared secundaria masiva.',path:'Hongos de la madera producen lacasas para degradar lignina → podredumbre blanca/parda.',cur:'La lignina es el segundo polímero orgánico más abundante en la biosfera, después de la celulosa.'},
  primary_wall_x:{name:'Pared Primaria Xilemal',emoji:'🧱',fn:'Plantilla inicial de la pared celular. Parcialmente degradada durante la maduración del xilema.',loc:'Entre la membrana plasmática y la pared secundaria.',struct:'Celulosa (~30%), hemicelulosa (~30%), pectinas (~30%), proteínas de pared (~10%).',proc:'Durante la diferenciación, se deposita la pared secundaria sobre ella. La pared primaria persiste en punteaduras.',diff:'Presente en todas las células vegetales. La pared secundaria es adicional en células especializadas.',path:'La degradación de pectinas por patógenos debilita la unión entre células del xilema.',cur:'Las microfibrillas de celulosa de la pared primaria se orientan al azar para permitir el crecimiento isotrópico.'},
  pit_membrane:{name:'Membrana de Punteadura',emoji:'🔗',fn:'Permite el flujo de agua entre células del xilema. Es el eslabón clave de la conductividad hídrica.',loc:'Pared primaria y lámina media que cierra la punteadura areolada.',struct:'Celulosa y pectinas. En gimnospermas: toro central rígido + márgum flexible.',proc:'El agua fluye por los poros de la membrana de punteadura. Diferencia de presión entre células.',diff:'La conductividad de la membrana de punteadura determina la eficiencia del xilema.',path:'Embolia xilémica: burbujas bloquean el flujo en las punteaduras → marchitamiento.',cur:'El tamaño de poro de la membrana (0.1–1 µm) excluye patógenos pero permite el paso del agua.'},
  lumen:{name:'Lumen Vascular',emoji:'💧',fn:'Canal hueco por el que fluye la solución xilémica (agua + minerales) bajo tensión negativa.',loc:'Espacio interno de los vasos y traqueidas del xilema.',struct:'Vacío central en células muertas. La savia xilémica fluye en continuo apoplástico.',proc:'Flujo de agua por gradiente de potencial hídrico (teoría cohesión-tensión). Presiones de -1 a -10 MPa.',diff:'El lumen xilemático conduce agua muerta (por tensión), mientras el floema conduce con presión positiva.',path:'La cavitación (rotura de la columna de agua) interrumpe el flujo y provoca marchitamiento.',cur:'El agua asciende por el xilema sin gastar energía: la fuerza motriz es la evapotranspiración foliar.'},
  bordered_pit:{name:'Punteadura Areolada',emoji:'⭕',fn:'Válvula especializada entre traqueidas. Regula el flujo de agua y previene la propagación de embolias.',loc:'Pared lateral entre traqueidas adyacentes, especialmente en gimnospermas.',struct:'Cámara con membrana de punteadura (toro + márgum). El toro puede sellar la punteadura si hay embolia.',proc:'El flujo de agua abre el márgum. La diferencia de presión desplaza el toro → sellado de emergencia.',diff:'Gimnospermas: punteaduras areoladas con toro. Angiospermas: simples, sin toro diferenciado.',path:'A mayor sequía, más punteaduras selladas → pérdida de conductividad hídrica → estrés hídrico.',cur:'El mecanismo toro-márgum es una válvula de seguridad que protege el árbol de la embolia.'},
  bordered_pit2:{name:'Punteadura Areolada (2)',emoji:'⭕',fn:'Segunda punteadura areolada. El árbol tiene miles de estas válvulas para redundancia hidráulica.',loc:'Pared lateral de traqueidas, posición opuesta a la primera.',struct:'Idéntica a la punteadura areolada primaria. Funcionan en pares ("aspirada" y "no aspirada").',proc:'Cuando una se sella, el par opuesto asume mayor flujo. Redunda la conductividad.',diff:'Su distribución y densidad varía entre especies: las coníferas de zonas secas tienen más.',path:'Fúngicidas comerciales se aplican para reducir la degradación de punteaduras por Ophiostoma spp.',cur:'Una traqueida de pino puede tener hasta 300 punteaduras areoladas en sus paredes.'},
  spiral_band:{name:'Banda Espiral de Lignina (Superior)',emoji:'🌀',fn:'Engrosamiento en espiral de la pared interna. Permite la elongación del vaso mientras conduce agua.',loc:'Pared interna de los vasos protoximáticos (xilema primario joven).',struct:'Bandas de lignina y celulosa dispuestas helicoidalmente. El lumen no está completamente lignificado.',proc:'Las espirales permiten que el vaso se estire sin perder su función durante el crecimiento del órgano.',diff:'Xilema primario joven: anular y espiral. Xilema maduro: escalariforme, reticulado o punteado.',path:'Los vasos en espiral se forman primero y son los más frágiles al estrés mecánico.',cur:'Las bandas espirales del metaxilema se parecen al resorte de un muelle: flexibles y resistentes a la vez.'},
  spiral_band2:{name:'Banda Espiral de Lignina (Inferior)',emoji:'🌀',fn:'Engrosamiento espiral en la zona basal del vaso. Continúa el patrón helicoidal de refuerzo.',loc:'Zona inferior de la traqueida o elemento de vaso.',struct:'Igual que la banda espiral superior. La espiral puede cambiar de sentido (dextro/levógiro).',proc:'Mantiene la conductividad hídrica con flexibilidad. Permite el transporte continuo sin colapso.',diff:'En el xilema secundario (madera) predominan los vasos punteados, no los en espiral.',path:'Insectos xilófagos dañan primero los vasos en espiral por ser los menos lignificados.',cur:'El patrón en espiral de la lignina fue optimizado evolutivamente: resiste mejor la tensión que la compresión.'},
  plasmalemma_x:{name:'Plasmalema Residual',emoji:'🌐',fn:'Membrana plasmática remanente en células del xilema vivo (parénquima xilemático). Controla los minerales.',loc:'En células vivas del xilema (parénquima de rayo, parénquima axial).',struct:'Bicapa lipídica estándar. Las células muertas del xilema no tienen plasmalema.',proc:'Controla la carga y descarga de iones (K⁺, Mg²⁺) en la savia xilémica. Almacenamiento de almidón.',diff:'El xilema es mixto: células muertas (vasos, traqueidas) + células vivas (parénquima).',path:'El parénquima xilemático es reserva de azúcares: es el tejido que aprovecha el mazú fúngico.',cur:'Las células de parénquima xilemático viven décadas, mientras los vasos conductores mueren en días.'},
  tylosis:{name:'Tílosis',emoji:'🔴',fn:'Oclusión de los vasos del xilema por intrusión de células de parénquima. Respuesta defensiva.',loc:'Interior del lumen xilemático, donde las células parénquima se hinchen hacia adentro.',struct:'Células de parénquima que se expanden a través de las punteaduras hacia el lumen del vaso.',proc:'Se forman tras infección, senescencia o daño. Obstruyen el paso de patógenos vasculares.',diff:'Exclusivas del xilema. Las tílosis de los vasos son la base de la madera de corazón (duramen).',path:'Fusarium y Verticillium son bloqueados por tílosis, pero en exceso causan marchitamiento.',cur:'El duramen de las maderas duras (roble, teca) es rico en tílosis: por eso son resistentes a la pudrición.'},
  // ── MYOCYTE ──
  myocyte_membrane:{name:'Sarcolema',emoji:'🌐',fn:'Membrana plasmática especializada de la fibra muscular. Transmite el potencial de acción al interior mediante los túbulos T e integra señales mecánicas y químicas.',loc:'Límite externo de la fibra muscular esquelética. Se invagina formando los túbulos T.',struct:'Bicapa fosfolipídica con canales Nav1.4 (voltaje-dependientes), caveolas (invaginaciones con caveolina-3) y el complejo glicoproteico de distrofina.',proc:'Despolarización → apertura Nav1.4 → propagación del PA → invaginación tubular → acoplamiento E-C.',diff:'Contiene caveolas y canales Nav1.4 únicos del músculo. A diferencia del sarcolema cardíaco, usa Nav1.4 en lugar de Nav1.5.',path:'Mutaciones Nav1.4 → miotonía congénita (relajación lenta) y parálisis periódica. Pérdida de distrofina → distrofia de Duchenne.',cur:'La distrofina ancla el citoesqueleto de actina al sarcolema. Sin ella, el sarcolema se rompe por las fuerzas contráctiles repetidas.'},
  nucleus_m:{name:'Núcleo Periférico',emoji:'🟣',fn:'Controla la expresión génica de proteínas contráctiles (actina, miosina, titin, troponina) en su dominio miconuclear local.',loc:'Periférico, bajo el sarcolema. Desplazado de la zona central por las miofibrillas durante la diferenciación.',struct:'Oval aplanado. Núcleo activo con cromatina laxa. Nucléolo visible. La fibra madura puede tener cientos de núcleos.',proc:'Síntesis de ARNm para actina, miosina, distrofina y reguladores. Cada núcleo gobierna un dominio citoplasmático de ~25 µm.',diff:'La fibra muscular es un sincicio multinucleado (fusión de mioblastos). Sus núcleos son periféricos, a diferencia del músculo cardíaco (1 núcleo central).',path:'Distrofia muscular de Duchenne: mutación en distrofina en cromosoma X. Distrofias de cinturas: por proteínas del complejo distrofina.',cur:'Las células satélite son mioblastos quiescentes bajo el sarcolema que se activan para regenerar la fibra muscular lesionada.'},
  nucleus_m2:{name:'Núcleo Periférico (2)',emoji:'🟣',fn:'Segundo núcleo periférico. Apoya la síntesis de proteínas contráctiles en su dominio citoplasmático local.',loc:'Periférico, en el extremo opuesto de la fibra. Cada fibra puede tener 50-200 núcleos espaciados ~25 µm.',struct:'Idéntico al primer núcleo periférico. Forma oval aplanada, cromatina activa.',proc:'El "dominio miconuclear": cada núcleo gobierna la expresión proteica de ~37.500 µm³ de citoplasma adyacente.',diff:'En miopatías centronucleares (DNM2), los núcleos migran al centro de la fibra → disfunción contráctil severa.',path:'Miopatía centronuclear ligada al X (MTM1), autosómica dominante (DNM2). Debilidad generalizada desde el nacimiento.',cur:'Las células satélite aportan nuevos núcleos durante la hipertrofia muscular inducida por ejercicio (adición de mionúcleos).'},
  sarcomere:{name:'Sarcómero',emoji:'🔴',fn:'Unidad contráctil básica del músculo. Genera fuerza por deslizamiento de filamentos gruesos (miosina) sobre delgados (actina).',loc:'Dentro de las miofibrillas, repetidos en serie. Longitud en reposo: ~2.2 µm.',struct:'Banda A (miosina+actina); Banda I (solo actina); Disco Z (ancla actina); Zona H (miosina sola); Línea M (centro). Titina como resorte.',proc:'Ca²⁺+troponina C → desplazamiento tropomiosina → sitios actina expuestos → ciclo puentes cruzados → power stroke → deslizamiento.',diff:'La longitud del sarcómero determina la fuerza: máxima a 2.2 µm (plataforma fuerza-longitud). A <1.6 µm o >3.6 µm la fuerza cae.',path:'Cardiomiopatía hipertrófica: mutación en β-miosina cardiaca (MYH7). Miopatía nemalínica: mutaciones en actina, tropomiosina, troponina.',cur:'El omecamtiv mecarbil es un activador directo de la miosina cardiaca en investigación clínica para insuficiencia cardiaca.'},
  myofibril:{name:'Miofibrilla',emoji:'🟥',fn:'Genera contracción muscular por deslizamiento de filamentos. Ocupa ~80% del volumen de la fibra muscular.',loc:'Dispuesta longitudinalmente, recorre toda la longitud de la fibra. Diámetro: 1–2 µm.',struct:'Haces de filamentos delgados (actina 7 nm + troponina + tropomiosina) y gruesos (miosina 15 nm) organizados en sarcómeros en serie.',proc:'Power stroke: cada ciclo actina-miosina consume 1 ATP y desplaza el filamento ~10 nm (fuerza ~5 pN por cabeza de miosina).',diff:'Tipo I (lento, oxidativo): isoforma β-MHC, más mitocondrias. Tipo IIa (rápido-oxidativo): α-MHC. Tipo IIx (glucolítico puro): muy alta potencia.',path:'Sarcopenia (pérdida de miofibrillas con el envejecimiento): pérdida de fuerza y masa muscular. Atrofia por desuso: degradación proteosómica de miosina.',cur:'El entrenamiento de fuerza activa mTORC1 → síntesis proteica miofibrilar → hipertrofia. La miostatina inhibe este proceso.'},
  t_tubule:{name:'Túbulo T',emoji:'🔵',fn:'Conduce el potencial de acción al interior de la fibra muscular (hasta 50 µm de profundidad) para activar el RS y disparar la contracción.',loc:'Invaginación perpendicular del sarcolema. En músculo esquelético: en la unión de bandas A e I.',struct:'Extensión del sarcolema con DHPR/Cav1.1 (sensor de voltaje). Flanqueado por cisternas terminales del RS → tríada.',proc:'PA → DHPR detecta voltaje → cambio conformacional → activa RyR1 del RS → Ca²⁺ → troponina C → contracción (acoplamiento E-C mecánico).',diff:'Esquelético: DHPR activa RyR1 mecánicamente (sin Ca²⁺ extracelular). Cardíaco: DHPR (Cav1.2) deja entrar Ca²⁺ → dispara CICR en RS.',path:'Miopatía centronuclear (DNM2, MTM1): morfología anómala de túbulos T. Enfermedad de Andersen-Tawil (Kir2.1): paralisis periódica.',cur:'El dantroleno bloquea RyR1, tratando la hipertermia maligna. La malignant hyperthermia es una urgencia anestésica mortal si no se trata.'},
  sr:{name:'Retículo Sarcoplasmático',emoji:'🟡',fn:'Reservorio intracelular de Ca²⁺. Libera Ca²⁺ al inicio de la contracción y lo recapta para la relajación.',loc:'Red de membranas lisas que rodea cada miofibrilla, paralela al eje longitudinal.',struct:'Membrana sin ribosomas con SERCA1a (Ca²⁺-ATPasa, músculo rápido) o SERCA2a (lento/cardíaco). Lumen con calsecuestrina.',proc:'Liberación: RyR1 abre → [Ca²⁺]i de 100 nM a 10 µM (100×). Recaptación: SERCA2a bombea Ca²⁺ de regreso → relajación.',diff:'RS muscular = RE liso especializado. Más organizado y abundante que el RE de otras células. SERCA es la proteína más abundante del RS.',path:'Hipertermia maligna (RyR1 hipersensible). SERCA2a reducida en IC crónica → disfunción diastólica. Enfermedad de Brody (SERCA1 deficiente).',cur:'Terapia génica AAV-SERCA2a fue evaluada en IC (ensayo CUPID). El fosfolamban inhibe SERCA2a: su silenciamiento mejora la función cardiaca.'},
  terminal_cisterna:{name:'Cisterna Terminal',emoji:'🔶',fn:'Amplificador de Ca²⁺. Forma la tríada con el túbulo T para el acoplamiento excitación-contracción eficiente.',loc:'Dilataciones del RS flanqueando el túbulo T en la unión de bandas A e I.',struct:'Alta densidad de RyR1 (receptor de rianodina), calsecuestrina, triadin y junctina en el lumen.',proc:'DHPR en túbulo T → RyR1 en cisterna → apertura → liberación masiva de Ca²⁺ al sarcoplasma → contracción.',diff:'La tríada (2 cisternas + 1 túbulo T) es exclusiva del músculo esquelético. El cardíaco tiene díadas (1 cisterna + 1 túbulo T).',path:'Hipertermia maligna (RyR1 hipersensible). Miopatías ligadas a RyR1: central core disease, multiminicore. CASQ1 mutado: miopatía vacuolar.',cur:'Las "rycal" (S107, ARM210) son moléculas que estabilizan RyR1 para tratar miopatías ligadas a RyR1. En ensayos clínicos.'},
  mito_m:{name:'Mitocondria Muscular',emoji:'🔴',fn:'Produce ATP por fosforilación oxidativa para la ATPasa de miosina y la bomba SERCA. Determina la resistencia a la fatiga.',loc:'Organizadas en hileras entre miofibrillas y bajo el sarcolema. Especialmente abundantes en fibras tipo I.',struct:'Crestas muy desarrolladas. Alto contenido en citocromos, ATP sintasa, enzimas del ciclo de Krebs y β-oxidación.',proc:'β-oxidación de AGL + ciclo de Krebs + cadena respiratoria → ~30 ATP/glucosa o ~100 ATP/ácido palmítico.',diff:'Fibras tipo I (~30% volumen mitocondrial) vs tipo IIb (~5%). El entrenamiento aeróbico aumenta la densidad mitocondrial.',path:'Miopatías mitocondriales: MELAS (ACV, encefalopatía), MERRF (mioclonías), intolerancia al ejercicio severa.',cur:'PGC-1α es el regulador maestro de la biogénesis mitocondrial. El ejercicio aeróbico activa AMPK → PGC-1α → nuevas mitocondrias.'},
  mito_m2:{name:'Mitocondria (2)',emoji:'🔴',fn:'Segunda mitocondria muscular. Contribuye a la producción de ATP aeróbico y al metabolismo de lactato.',loc:'Entre miofibrillas, zona intermedia de la fibra muscular.',struct:'Doble membrana, crestas, matriz con enzimas del ciclo de Krebs y β-oxidación.',proc:'Oxida lactato (lanzadera célula-célula), ácidos grasos y cuerpos cetónicos. Produce calor (termogénesis muscular).',diff:'En fibras IIa (rápidas-oxidativas), las mitocondrias son intermedias en abundancia y eficiencia.',path:'La disfunción mitocondrial es un mecanismo central de la sarcopenia y de la resistencia a la insulina muscular.',cur:'La creatina-fosfato actúa como tampón de ATP en los primeros 5-10 s del ejercicio intenso antes de que las mitocondrias alcancen velocidad máxima.'},
  glycogen_m:{name:'Glucógeno Muscular',emoji:'🍬',fn:'Reserva energética rápida para glucólisis anaeróbica en ejercicio intenso. Uso exclusivamente local.',loc:'Entre miofibrillas, cerca de mitocondrias y sarcómeros. Rosetas α de ~200 nm.',struct:'Polisacárido ramificado de glucosa (α-1,4 y α-1,6). ~55.000 glucosas/partícula β. Asociado a glucógeno fosforilasa.',proc:'Activación por Ca²⁺ (contracción) y AMP (baja energía) → glucógeno fosforilasa b→a → glucosa-6-P → glucólisis anaeróbica.',diff:'A diferencia del hígado, el músculo carece de glucosa-6-fosfatasa → no puede exportar glucosa. El glucógeno muscular es de uso local exclusivo.',path:'Enfermedad de McArdle (tipo V): déficit de glucógeno fosforilasa → rabdomiólisis por ejercicio, mioglobinuria. Test: ausencia de lactato en isquemia.',cur:'Carga de carbohidratos pre-competición llena los depósitos de glucógeno. Una dieta alta en CHO puede triplicar el glucógeno muscular.'},
  myoglobin:{name:'Mioglobina',emoji:'🟥',fn:'Almacena O₂ intracelular y facilita su difusión hacia las mitocondrias. Reserva de O₂ para isquemia transitoria.',loc:'Sarcoplasma de fibras tipo I (rojas). Confiere el color rojo oscuro al músculo aeróbico.',struct:'Monómero globínico (153 aa) con grupo hemo (Fe²⁺). P50 ≈ 2.8 mmHg (alta afinidad vs hemoglobina P50 ≈ 26 mmHg).',proc:'Capta O₂ de capilares → difusión facilitada → mitocondrias. Libera O₂ solo en hipoxia local severa. No muestra cooperatividad.',diff:'Mioglobina: monómero, curva hiperbólica, P50 bajo. Hemoglobina: tetrámero, curva sigmoide, cooperativa. Musculatura de cetáceos tiene 10× más Mb.',path:'Rabdomiólisis → mioglobinuria → insuficiencia renal aguda (tubulotóxica). Biomarcador de IAM: se eleva a las 2h (sensible, poco específico).',cur:'La mioglobina sérica es el marcador más precoz de necrosis miocárdica (2h vs troponina 3-6h), aunque carece de especificidad cardíaca.'},
  neuromuscular_jn:{name:'Unión Neuromuscular',emoji:'⚡',fn:'Transmite la señal eléctrica del motoneurón α a la fibra muscular mediante acetilcolina. Punto de control de la contracción voluntaria.',loc:'Placa motora en la zona media de la fibra. Cada fibra tiene exactamente 1 UNM.',struct:'Terminal axónico (vesículas ACh, Ca²⁺) + hendidura sináptica (AChE) + placa motora (AChR nicotínico, pliegues secundarios).',proc:'PA → Ca²⁺ entra en terminal (VGCC) → SNARE → exocitosis ACh → AChR → despolarización EPP → PA muscular → contracción.',diff:'La UNM es química y usa AChR nicotínico ionotrópico. La sinapsis neuronal puede usar GABA, glutamato, etc. 1 motoneurona → 10-2000 fibras.',path:'Miastenia gravis (anti-AChR). Síndrome Lambert-Eaton (anti-VGCC). Botulismo (toxina cliva SNARE). ELA (destrucción motoneurona).',cur:'La piridostigmina (inhibidor AChE) aumenta la vida de ACh en la hendidura: tratamiento sintomático de la miastenia. La timectomía puede ser curativa.'},
  // ── TCELL ──
  tcell_membrane:{name:'Membrana del Linfocito T',emoji:'🛡️',fn:'Barrera selectiva con alta densidad de receptores de señalización: TCR, CD3, CD4/CD8, CD28, CD45 y LFA-1. Plataforma de integración de señales inmunes organizadas en balsas lipídicas.',loc:'Límite externo del linfocito T. Los receptores se concentran en balsas lipídicas ricas en colesterol/esfingomielina.',struct:'Bicapa fosfolipídica con ~30.000 TCR por µm². Balsas lipídicas (lipid rafts) concentran Lck, CD4/CD8 y TCR activos. LFA-1 y CD44 en zonas periféricas.',proc:'Reconocimiento pMHC → clustering de TCR en balsas → formación de sinapsis inmunológica → activación de Lck/ZAP-70 → cascada de señalización → IL-2, proliferación.',diff:'A diferencia de otras células, la membrana del linfocito T puede reorganizarse completamente en minutos para formar la sinapsis inmunológica con alta direccionalidad.',path:'Deficiencia de CD3γ o CD3δ → SCID. Ausencia de CD4 → inmunodeficiencia (VIH destruye CD4+). Mutaciones en ZAP-70 → SCID con CD4 funcional pero sin CD8.',cur:'Los anticuerpos anti-CD3 (muromonab, OKT3) son inmunosupresores. Las CAR-T cells insertan un receptor quimérico en la membrana: usan dominios de CD3ζ para señalización.'},
  nucleus_t:{name:'Núcleo del Linfocito T',emoji:'🟣',fn:'Integra señales de activación. NFAT, NF-κB y AP-1 translocan al núcleo tras la señal del TCR activando genes efectores: IL-2, IFN-γ, perforina, FasL y Bcl-2.',loc:'Central, con alta relación núcleo/citoplasma (~85% del volumen celular en T naive).',struct:'Cromatina condensada (heterocromatina periférica) en T naive. Se descondensa al activarse. Nucléolo pequeño en reposo; protuberante en T activado/blástico.',proc:'Señal TCR → Ca²⁺ → calcineurina → NFAT desfosforilado → entra al núcleo → activa IL-2. PKC → IκB degradado → NF-κB nuclear → supervivencia y proliferación.',diff:'T naive: cromatina condensada, poco ARNm. T blástico (activado): cromatina abierta, ciclo cada 6-8h, síntesis masiva de citocinas y proteínas efectoras.',path:'Leucemia linfocítica aguda T (LLA-T): proliferación descontrolada de T inmaduros. Linfoma anaplásico de células grandes (ALCL): T maduros con mutaciones ALK.',cur:'Los inhibidores de calcineurina (ciclosporina A, tacrolimus) bloquean la entrada de NFAT al núcleo: inmunosupresores estándar en trasplante de órganos sólidos.'},
  nucleolus_t:{name:'Nucléolo del Linfocito T',emoji:'🔵',fn:'Fábrica de ribosomas. En T naive casi invisible; en T activado se agranda masivamente por la alta demanda de síntesis proteica (IL-2, granzimas, receptores).',loc:'Interior del núcleo. Puede haber 1-2 nucléolos por núcleo en T activado.',struct:'FC (fibrilar central) + DFC (fibrilar densa) + GC (granular). Asociado a regiones organizadoras del nucléolo (NOR) en cromosomas 13,14,15,21,22.',proc:'Activación vía TCR → c-Myc activa transcripción de ARNr → síntesis masiva de ribosomas 80S → soporte de la explosión biosintética del T blástico.',diff:'El tamaño del nucléolo es marcador de activación linfocitaria: grande en blastos, mínimo en cells naive y memoria. Criterio histológico en linfomas agresivos.',path:'En linfomas T de alto grado el nucléolo es prominente. c-Myc sobreexpresado en linfoma de Burkitt T-like amplifica nucleologénesis descontrolada.',cur:'Los inhibidores BET/BRD4 (JQ1, I-BET) suprimen c-Myc y la transcripción de ARNr: en desarrollo para linfomas T y leucemias refractarias.'},
  tcr_cd3:{name:'Complejo TCR-CD3',emoji:'🔑',fn:'Receptor específico de antígeno del linfocito T. Reconoce péptidos presentados por MHC en células presentadoras (CPA) y genera la señal primaria de activación linfocitaria.',loc:'Membrana plasmática. Se concentra en balsas lipídicas y migra al cSMAC de la sinapsis inmunológica.',struct:'TCR (heterodímero αβ, dominios V y C Ig-like) + CD3 (γε, δε, ζζ). Las colas citosólicas de CD3ζ tienen 3 ITAMs (6 tirosinas totales) fosforiladas por Lck.',proc:'pMHC → TCR reconoce → Lck fosforila ITAM de CD3ζ → ZAP-70 reclutado y activado → fosforila LAT/SLP-76 → PLCγ→DAG+IP3 y PI3K→PIP3 → PKC+Ca²⁺ → NF-κB+NFAT.',diff:'El TCR NO reconoce antígenos libres (a diferencia del BCR): requiere presentación por MHC. Diversidad: recombinación V(D)J → 10^15-18 especificidades posibles.',path:'Síndrome de Omenn: mutaciones RAG1/2 → TCR muy limitado → SCID con autoinmunidad. Timoma: selección tímica anómala → autoinmunidad.',cur:'Las células CAR-T fusionan dominios de reconocimiento (ScFv anti-CD19, anti-CD22, anti-BCMA) con la señalización de CD3ζ+CD28 o CD3ζ+4-1BB. FDA-aprobadas para leucemias y mieloma.'},
  immune_synapse:{name:'Sinapsis Inmunológica',emoji:'⚡',fn:'Interfaz organizada (IS) entre el linfocito T y la CPA o célula diana. Coordina la señalización del TCR, secreción de citocinas y degranulación citotóxica direccional.',loc:'Zona de contacto entre el linfocito T y la célula presentadora de antígeno. Se forma en 5-10 minutos.',struct:'cSMAC (centro: TCR, PKCθ, Lck, APC) + pSMAC (anillo: LFA-1/ICAM-1, talina, actina) + dSMAC (periferia: CD45, fosfatasas). Arquitectura SMAC.',proc:'TCR se activa en la periferia (microclusters) → migra al cSMAC → degradación por ubiquitinación. Golgi y MTOC se polarizan hacia IS. CTL: degranulación en cSMAC. Th: citocinas secretadas en IS.',diff:'En CTL la IS permite secreción direccional de perforina/granzima solo hacia la diana (no bystander). En Th la IS orienta IL-2/IFN-γ hacia la CPA.',path:'Síndrome de Chediak-Higashi y HLH: defectos en polarización de gránulos en la IS → incapacidad de matar. DOCK8: defecto en sinapsis → inmunodeficiencia primaria.',cur:'La eficiencia de la IS determina la capacidad citolítica de CTL terapéuticos. Engagers biespecíficos (blinatumomab anti-CD19/CD3) crean IS artificiales para matar células tumorales.'},
  mito_t:{name:'Mitocondria del Linfocito T',emoji:'🔴',fn:'Produce ATP y regula la reprogramación metabólica naive→activado. Controla la señalización de Ca²⁺ y la apoptosis intrínseca del linfocito.',loc:'Perinuclear en T naive. Se amplifica y redistribuye masivamente al activarse el linfocito.',struct:'Doble membrana, crestas variables según estado metabólico. Morfología elongada en T memoria (OXPHOS); fragmentada en T efector (glucólisis).',proc:'T naive: OXPHOS (eficiente). T efector: Warburg (glucólisis aeróbica, rápida) por mTORC1/c-Myc. T memoria: OXPHOS con alta capacidad de reserva (spare respiratory capacity).',diff:'La mitocondria del linfocito T controla tres destinos: activación (Ca²⁺ buffer, ATP), apoptosis (citocromo c → caspasa-9) y agotamiento (disfunción en T exhausted).',path:'T exhausted en infecciones crónicas/cáncer: disfunción mitocondrial, PD-1 alto, IL-2 bajo → incapacidad de controlar la infección/tumor.',cur:'Anti-PD-1/CTLA-4 (nivolumab, pembrolizumab, ipilimumab) revierten parcialmente el agotamiento metabólico. La biogénesis mitocondrial es objetivo para mejorar CTL en inmunoterapia.'},
  mito_t2:{name:'Mitocondria (2)',emoji:'🔴',fn:'Apoya la producción de ROS señalizadores (activan NF-κB) y la síntesis de nucleótidos para la proliferación. Las mitocondrias linfocitarias forman redes dinámicas.',loc:'Citoplasma periférico. Se fisionan (DRP1) durante la activación para favorecer la glucólisis.',struct:'Doble membrana, crestas. La fusión mitocondrial (MFN1/2) favorece OXPHOS; la fisión (DRP1) favorece glucólisis anaeróbica.',proc:'ROS de la cadena respiratoria activan NF-κB como segundo mensajero en la respuesta del TCR. Complejo I es fuente principal de ROS señalizadores.',diff:'Los linfocitos T memoria tienen alta spare respiratory capacity (SRC): responden con rapidez al reencuentro antigénico usando la reserva mitocondrial.',path:'Disfunción en DRP1 afecta la diferenciación de T efectores a T memoria. IRGM: regulador de mitofagia en linfocitos T, mutado en enfermedad inflamatoria intestinal.',cur:'La metformina (activa AMPK, inhibe mTORC1) puede reconfigurar el metabolismo de T cells hacia OXPHOS: estudiada como inmunomodulador en autoinmunidad y vacunas.'},
  er_t:{name:'Retículo Endoplasmático (Linfocito T)',emoji:'🟠',fn:'Reservorio de Ca²⁺ intracelular. La señalización IP3→IP3R libera Ca²⁺ que activa calcineurina→NFAT→IL-2. Sede del SOCE (store-operated Ca²⁺ entry) vía STIM1-Orai1.',loc:'Perinuclear y disperso. Se conecta al sarcolema via STIM1 para el vaciamiento del RE activa la entrada de Ca²⁺ extracelular.',struct:'RE liso predominante. IP3R tipo 1 (canal de Ca²⁺ activado por IP3). SERCA recapta Ca²⁺. STIM1 en la membrana del RE detecta el vaciamiento.',proc:'PLCγ (activada por ZAP-70/LAT) → IP3 → IP3R del RE → liberación Ca²⁺ → calmodulina → calcineurina (fosfatasa) → NFAT desfosforilado → entra al núcleo → transcripción IL-2, IFN-γ.',diff:'El vaciamiento del RE activa SOCE: STIM1 oligomeriza y contacta Orai1 en la membrana → CRAC current → Ca²⁺ sostenido → activación linfocitaria completa.',path:'Mutaciones en STIM1 u Orai1 → SCID por fallo en señalización Ca²⁺ de linfocitos T y B. Fenotipo: ausencia de linfocitos funcionales, infecciones recurrentes graves.',cur:'Ciclosporina A y tacrolimus actúan aguas abajo del Ca²⁺: inhiben calcineurina. CRAC channel blockers (Synta66, CM4620) se estudian en enfermedades autoinmunes.'},
  golgi_t:{name:'Aparato de Golgi del Linfocito T',emoji:'🟤',fn:'Procesa y secreta citocinas (IL-2, IFN-γ, TNF-α). Se polariza hacia la sinapsis inmunológica durante la respuesta citotóxica para secreción direccional.',loc:'Perinuclear en T naive. Al activarse, el MTOC (centrosoma) y el Golgi migran hacia la IS en <30 min.',struct:'4-6 cisternas apiladas. Cara cis (recibe del RE) y trans (envía vesículas secretoras y gránulos líticos).',proc:'Glicosilación y empaquetado de citocinas. Polarización: señal TCR → PKCθ activa → reorientación del MTOC → Golgi migra hacia IS → degranulación/secreción dirigidas.',diff:'La polarización del Golgi es característica exclusiva de la respuesta CTL: asegura que la perforina y granzimas se liberen solo hacia la célula diana (no dañan al propio CTL).',path:'HPS2 (Hermansky-Pudlak tipo 2): defecto AP-3 del Golgi → tráfico anómalo de gránulos líticos → HLH (linfohistiocitosis hemofagocítica). Letal sin trasplante de médula.',cur:'La polarización del Golgi se evalúa como predictor de función CTL en inmunoterapia. Células CAR-T con Golgi no polarizable tienen menor citotoxicidad in vivo.'},
  cytotox_granule:{name:'Gránulo Citotóxico',emoji:'🟢',fn:'Orgánulo lisosomal especializado del CTL. Contiene perforina y granzimas para matar células diana infectadas o tumorales por apoptosis.',loc:'Citoplasma. Migran hacia el cSMAC de la IS tras activación del TCR en contacto con la célula diana.',struct:'Vesícula de membrana ácida (pH 5). Perforina (pore-forming protein) + granzima B/A (serina proteasas) + granulisina + FasL. Granulisina inhibe granzimas a pH ácido.',proc:'Exocitosis Ca²⁺-dependiente en IS → perforina forma poros (en membrana diana a pH neutro) → granzima B entra → cliva BID → mitocondria → citocromo c → caspasa-9/3 → apoptosis diana.',diff:'A diferencia de mastocitos, la degranulación del CTL es polarizada (solo hacia la diana) y no causa daño bystander. El CTL es protegido por cluesterina y CD59 en su propia membrana.',path:'Linfohistiocitosis hemofagocítica (HLH): mutaciones en PRF1 (perforina), UNC13D (Munc13-4), RAB27A, STX11 → incapacidad de matar → hiperinflamación sistémica fatal.',cur:'CD107a (LAMP-1) se transloca a membrana tras degranulación: marcador de CTL funcional. Usado para evaluar respuestas CTL en vacunas, inmunoterapia y monitorización post-CAR-T.'},
  cytotox_granule2:{name:'Gránulo Citotóxico (2)',emoji:'🟢',fn:'Segundo gránulo lítico. El CTL puede tener 10-20 gránulos orientados hacia la IS. La granzima A activa una vía de apoptosis independiente de caspasas.',loc:'Citoplasma del CTL, polarizado hacia el cSMAC de la IS.',struct:'Igual al gránulo primario. Rico en granzima A (SET complex nucleasa → DNasa NM23-H1) además de granzima B y perforina.',proc:'Granzima A activa complejo SET → NM23-H1 corta ADN monocatenario → apoptosis sin caspasas (bypass de antiapoptóticos como BCL-2).',diff:'El CTL realiza "serial killing": libera gránulos, se separa de la diana muerta, regenera gránulos y ataca una nueva diana. Una CTL puede matar >10 dianas.',path:'Tumores BCL-2 alto son resistentes a granzima B pero no a granzima A (independiente de caspasas/BCL-2). Base racional para combinar inmunoterapia con venetoclax.',cur:'La granzima B recombinante se estudia como agente antitumoral directo. En inmunoterapia, la carga de gránulos (medida por TEM) predice la potencia del CTL CAR-T.'},
  lck_signaling:{name:'Plataforma Lck/ZAP-70',emoji:'🟡',fn:'Cascada de señalización proximal del TCR. Lck fosforila ITAMs de CD3ζ → ZAP-70 reclutado → LAT/SLP-76 → ramificación hacia Ca²⁺, Ras y PI3K para la activación completa.',loc:'Cara interna de la membrana plasmática, asociado a balsas lipídicas. Lck unido constitutivamente a CD4 (en Th) o CD8 (en CTL) vía motivo palmitoilado.',struct:'Lck (56 kDa): dominio SH4-dominio único-SH3-SH2-quinasa. ZAP-70 (70 kDa): tándem SH2 + dominio quinasa. LAT (adaptor transmembrana): 13 tirosinas fosforilables.',proc:'CD4/CD8 acerca Lck al TCR → Lck fosforila Y(ITAM)×6 en CD3ζ → SH2 de ZAP-70 une di-ITAM-P → ZAP-70 activado → fosforila LAT(Y136) → PLCγ1 reclutada → IP3+DAG.',diff:'La discriminación de señal débil (péptido propio) vs fuerte (pMHC extraño) se basa en cinética de Lck: ITAM monofosforilado = inhibitorio; difosforilado = activador.',path:'Deficiencia de ZAP-70 → SCID con CD4+ funcional pero sin CD8 (CD8 depende más de ZAP-70 para selección tímica). Mutación gain-of-function en ZAP-70 → artritis idiopática juvenil sistémica.',cur:'Fostamatinib (inhibidor Syk, homólogo de ZAP-70) aprobado para trombocitopenia inmune crónica. Inhibidores de Lck y ZAP-70 se estudian en artritis reumatoide y lupus.'},
  caspase_pathway:{name:'Vía FasL/Caspasas',emoji:'🔴',fn:'Mecanismo de citotoxicidad del CTL mediado por FasL que activa Fas (CD95) de la célula diana desencadenando apoptosis extrínseca. También regula la homeostasis linfocitaria (AICD).',loc:'FasL en membrana del CTL actúa sobre Fas de células diana Fas+. La vía intrínseca (mitocondria) actúa en el propio CTL para autolimitarse tras la respuesta.',struct:'FasL (trimérico, TNF family, 40 kDa) → Fas trimérico → FADD (via DD) → procaspasa-8 → DISC (death-inducing signaling complex) → caspasa-8 activa.',proc:'FasL trimérico → Fas trimeriza → FADD(DD-DED) → procaspasa-8 autoclivada → caspasa-8 activa → corta BID→tBID → inserta en mitocondria → citocromo c → caspasa-9 → caspasa-3 → apoptosis.',diff:'Citotoxicidad perforina/granzima (rápida, minutos, activa en células Fas-) vs FasL (más lenta, horas, crucial para células Fas+ como linfocitos B activados y T activados: homeostasis inmune).',path:'Síndrome linfoproliferativo autoinmune (ALPS): mutaciones en FAS → fallo en apoptosis linfocitaria → linfoproliferación masiva, autoanticuerpos. Mutaciones FASLG: ALPS tipo Ib.',cur:'Agonistas del receptor de muerte DR4/DR5 (TRAIL recombinante, anticuerpos anti-DR5) se estudian contra tumores Fas+. Venetoclax (anti-BCL2) potencia la apoptosis downstream de FasL/perforina.'},
};

